const SAVE_READER_REFERENCE_STATS = {"totalSaveItems":343,"crossChecked":229,"mapOnly":114,"rawcodeMismatches":[],"knownOverrides":[]};
const SAVE_READER_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

function srEncodeChar(ch) {
  const up = String(ch || "").toUpperCase();
  if (up >= "A" && up <= "Z") return up.charCodeAt(0) - 65;
  if (up >= "0" && up <= "9") return up.charCodeAt(0) - 48;
  return 0;
}

function srDecodeValues(code) {
  const s = String(code || "").toUpperCase().replace(/^\s*-L\s+/i, "").trim();
  const alphabet = SAVE_READER_ALPHABET;
  const codeLength = alphabet.length;
  const a = new Array(100).fill(0);
  const CONST = 1000000;
  let m = 0, i = 0, skip = -1;

  while (i < s.length) {
    for (let j = 0; j <= m; j++) a[j] *= codeLength;
    skip++;
    if (skip === 4) {
      skip = 0;
      i++;
      if (i >= s.length) break;
    }
    const c = s[i];
    let l = codeLength;
    while (true) {
      l--;
      if (l < 1 || alphabet[l] === c) break;
    }
    a[0] += l;
    let k = 0;
    for (let j = 0; j <= m; j++) {
      k = Math.floor(a[j] / CONST);
      a[j] -= k * CONST;
      a[j + 1] += k;
    }
    if (k > 0) m++;
    i++;
  }

  const abc = "0123456789-";
  let buffer = "";
  while (m >= 0) {
    let j = m;
    while (j > 0) {
      const k = Math.floor(a[j] / 11);
      a[j - 1] += (a[j] - k * 11) * CONST;
      a[j] = k;
      j--;
    }
    const k = Math.floor(a[0] / 11);
    const idx = a[0] - k * 11;
    buffer = abc[idx] + buffer;
    a[0] = k;
    if (a[m] === 0) m--;
  }

  const vals = [];
  let pos = 0, start = 0;
  while (pos < buffer.length) {
    while (pos < buffer.length && !(pos > 0 && buffer[pos] === "-" && buffer[pos - 1] !== "-")) pos++;
    const end = pos < buffer.length ? pos : buffer.length;
    vals.push(Number(buffer.slice(start, end)));
    start = pos + 1;
    pos++;
  }

  return { buffer, values: vals };
}

function srVerify(decoded, playerName) {
  const vals = decoded.values;
  if (!vals.length) return false;
  const checksum = vals[vals.length - 1];
  const lastDash = decoded.buffer.lastIndexOf("-");
  const dataPart = lastDash >= 0 ? decoded.buffer.slice(0, lastDash) : decoded.buffer;
  let total = 0;
  for (const ch of String(playerName || "")) total += srEncodeChar(ch);
  for (const ch of dataPart) total += srEncodeChar(ch);
  return total === checksum;
}

function srParseSave(decoded) {
  const values = decoded.values.slice(0, -1);
  let p = 0;
  const out = {
    gold: values[p++] ?? 0,
    heroes: [],
    inventory: [],
    lumber: 0,
    stashes: [[], [], [], [], [], []],
    revivePoint: null,
    prestige: null
  };

  const heroCount = values[p++] ?? 0;
  let inventoryCount = 0;
  for (let h = 0; h < heroCount; h++) {
    const heroIndex = values[p++] ?? 0;
    const xp = values[p++] ?? 0;
    const x = values[p++] ?? 0;
    const y = values[p++] ?? 0;
    inventoryCount = values[p++] ?? 0;
    out.heroes.push({
      index: heroIndex,
      rawcode: SAVE_READER_HEROES[heroIndex] || "",
      xp, x, y
    });
  }

  for (let n = 0; n < inventoryCount; n++) {
    const itemIndex = values[p++] ?? 0;
    const charges = values[p++] ?? 0;
    out.inventory.push({
      index: itemIndex,
      rawcode: SAVE_READER_ITEMS[itemIndex] || "",
      charges: charges === 0 ? 1 : charges,
      rawCharges: charges
    });
  }

  out.lumber = values[p++] ?? 0;

  for (let s = 0; s < 6; s++) {
    const count = values[p++] ?? 0;
    for (let n = 0; n < count; n++) {
      const itemIndex = values[p++] ?? 0;
      const charges = values[p++] ?? 0;
      out.stashes[s].push({
        index: itemIndex,
        rawcode: SAVE_READER_ITEMS[itemIndex] || "",
        charges: charges === 0 ? 1 : charges,
        rawCharges: charges
      });
    }
  }

  out.revivePoint = values[p++] ?? null;
  out.prestige = values[p++] ?? null;
  out.unparsed = values.slice(p);
  return out;
}

function srExtractTextMeta(text) {
  const id = (text.match(/ID:\s*([^"\r\n]+)/i) || [,""])[1].trim();
  const job = (text.match(/職業:\s*([^"\r\n]+)/i) || [,""])[1].trim();
  const level = Number((text.match(/等級:\s*(\d+)/i) || [,0])[1]);
  const code = (text.match(/-l\s+([A-Z0-9-]+)/i) || [,""])[1].trim();
  return { id, job, level, code };
}

function srItemMeta(item) {
  const meta = SAVE_READER_ITEM_META[item?.index] || {};
  return {
    ...item,
    cn: meta.cn || `物品 #${item?.index ?? "?"}`,
    en: meta.en || item?.rawcode || "",
    image: meta.image || "",
    nameSource: meta.nameSource || "rawcode", verifiedRawcode: !!meta.rawcode && meta.rawcode === item?.rawcode
  };
}

window.TwilightSaveReader = {
  decodeText(text) {
    const meta = srExtractTextMeta(text);
    if (!meta.code) throw new Error("找不到 -l 存檔碼");
    const decoded = srDecodeValues(meta.code);
    return {
      meta,
      verified: srVerify(decoded, meta.id),
      decoded,
      data: (() => {
        const data = srParseSave(decoded);
        data.inventory = data.inventory.map(srItemMeta);
        data.stashes = data.stashes.map(box => box.map(srItemMeta));
        return data;
      })()
    };
  }
};
